import type { SUPPORTED_SIZES } from "./constants.js";

export type GridSize = (typeof SUPPORTED_SIZES)[number];

export type BoardDescription = Readonly<{
  code: string;
  size: GridSize;
  seed: number;
  deck: readonly number[];
}>;

export type Selection =
  | Readonly<{ kind: "closed" }>
  | Readonly<{ kind: "one"; index: number }>
  | Readonly<{ kind: "mismatch"; first: number; second: number; remainingMs: number }>;

export type GameState = Readonly<{
  board: BoardDescription;
  matched: readonly number[];
  selection: Selection;
  moves: number;
  elapsedMs: number;
  started: boolean;
}>;
export const SUPPORTED_SIZES = [4, 6, 8, 10, 12, 14, 16] as const;
export const MISMATCH_MS = 800;
export const MAX_MOVES = 999_999;
export const MAX_ELAPSED_MS = 359_999_999;
