import { BOARD_VERSION, PARK_MILLER_MODULUS, SUPPORTED_SIZES } from "./constants.js";
import type { BoardDescription, GridSize, GameState } from "./types.js";

export { SUPPORTED_SIZES } from "./constants.js";

const isGridSize = (value: number): value is GridSize =>
  SUPPORTED_SIZES.some((size) => size === value);

export function parseBoardCode(text: string): BoardDescription | null {
  const match = /^(np1)-(4|6|8|10|12|14|16)-([1-9][0-9]*)$/.exec(text);
  if (!match) return null;
  const version = match[1];
  const sizeText = match[2];
  const seedText = match[3];
  if (!version || !sizeText || !seedText) return null;
  const size = Number(sizeText);
  const seed = Number(seedText);
  if (!isGridSize(size) || !Number.isSafeInteger(seed) || seed > PARK_MILLER_MODULUS - 1) return null;
  const code = `${version}-${size}-${seed}`;
  return Object.freeze({ code, size, seed, deck: Object.freeze(createDeck(size, seed)) });
}

function createDeck(size: GridSize, seed: number): number[] {
  const deck = Array.from({ length: size * size }, (_, index) => Math.floor(index / 2));
  let state = seed;
  const drawIndex = (bound: number): number => {
    const choices = PARK_MILLER_MODULUS - 1;
    const limit = Math.floor(choices / bound) * bound;
    let value = limit;
    while (value >= limit) {
      state = (state * 16_807) % PARK_MILLER_MODULUS;
      value = state - 1;
    }
    return value % bound;
  };
  for (let index = deck.length - 1; index > 0; index -= 1) {
    const other = drawIndex(index + 1);
    const currentFace = deck[index];
    const otherFace = deck[other];
    if (currentFace !== undefined && otherFace !== undefined) {
      deck[index] = otherFace;
      deck[other] = currentFace;
    }
  }
  return deck;
}

export function createGame(boardCode: string): GameState | null {
  const board = parseBoardCode(boardCode);
  if (!board) return null;
  return Object.freeze({
    board,
    matched: Object.freeze([]),
    selection: Object.freeze({ kind: "closed" as const }),
    moves: 0,
    elapsedMs: 0,
    started: false,
  });
}
import { MAX_ELAPSED_MS, MAX_MOVES, MISMATCH_MS } from "./constants.js";
import type { GameState, Selection } from "./types.js";

export function isWon(state: GameState): boolean {
  return state.matched.length === state.board.deck.length && state.selection.kind === "closed";
}

export function activateCard(state: GameState, index: number): GameState {
  if (!Number.isInteger(index) || index < 0 || index >= state.board.deck.length) return state;
  if (isWon(state) || state.matched.includes(index) || state.selection.kind === "mismatch") return state;
  if (state.selection.kind === "closed") {
    return Object.freeze({
      ...state,
      selection: Object.freeze({ kind: "one", index }),
      started: true,
    });
  }
  if (state.selection.index === index) return state;
  const moves = Math.min(MAX_MOVES, state.moves + 1);
  if (state.board.deck[state.selection.index] === state.board.deck[index]) {
    const matched = Object.freeze([...state.matched, state.selection.index, index]);
    return Object.freeze({ ...state, matched, selection: Object.freeze({ kind: "closed" }), moves, started: true });
  }
  const selection: Selection = Object.freeze({ kind: "mismatch", first: state.selection.index, second: index, remainingMs: MISMATCH_MS });
  return Object.freeze({ ...state, selection, moves, started: true });
}

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!Number.isSafeInteger(milliseconds) || milliseconds < 0 || isWon(state) || !state.started || milliseconds === 0) return state;
  const elapsedMs = Math.min(MAX_ELAPSED_MS, state.elapsedMs + milliseconds);
  if (state.selection.kind !== "mismatch") return Object.freeze({ ...state, elapsedMs });
  if (milliseconds >= state.selection.remainingMs) {
    return Object.freeze({ ...state, elapsedMs, selection: Object.freeze({ kind: "closed" }) });
  }
  const selection: Selection = Object.freeze({ ...state.selection, remainingMs: state.selection.remainingMs - milliseconds });
  return Object.freeze({ ...state, elapsedMs, selection });
}
import { FORMAT_VERSION, MAX_ELAPSED_MS, MAX_MOVES, MISMATCH_MS, SNAPSHOT_LIMIT_BYTES } from "./constants.js";
import { parseBoardCode } from "./board.js";
import type { GameState, Selection } from "./types.js";

export function encodeSnapshot(state: GameState): string {
  return JSON.stringify({
    version: FORMAT_VERSION,
    boardCode: state.board.code,
    matched: state.matched,
    selection: state.selection,
    moves: state.moves,
    elapsedMs: state.elapsedMs,
    started: state.started,
  });
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);
const hasKeys = (value: Record<string, unknown>, keys: readonly string[]): boolean =>
  Object.keys(value).length === keys.length && keys.every((key) => Object.hasOwn(value, key));
const isCount = (value: unknown, maximum: number): value is number =>
  typeof value === "number" && Number.isSafeInteger(value) && value >= 0 && value <= maximum;
const isPosition = (value: unknown, count: number): value is number =>
  typeof value === "number" && Number.isSafeInteger(value) && value >= 0 && value < count;

function readSelection(value: unknown, deck: readonly number[], matched: ReadonlySet<number>): Selection | null {
  if (!isRecord(value) || typeof value.kind !== "string") return null;
  if (value.kind === "closed" && hasKeys(value, ["kind"])) return Object.freeze({ kind: "closed" });
  if (value.kind === "one" && hasKeys(value, ["kind", "index"]) && isPosition(value.index, deck.length) && !matched.has(value.index)) {
    return Object.freeze({ kind: "one", index: value.index });
  }
  const first = value.first;
  const second = value.second;
  const remainingMs = value.remainingMs;
  if (value.kind !== "mismatch" || !hasKeys(value, ["kind", "first", "second", "remainingMs"])) return null;
  if (!isPosition(first, deck.length) || !isPosition(second, deck.length) || first === second) return null;
  if (matched.has(first) || matched.has(second) || deck[first] === deck[second]) return null;
  if (!isCount(remainingMs, MISMATCH_MS) || remainingMs === 0) return null;
  return Object.freeze({ kind: "mismatch", first, second, remainingMs });
}

export function decodeSnapshot(text: string): GameState | null {
  if (new TextEncoder().encode(text).byteLength > SNAPSHOT_LIMIT_BYTES) return null;
  let value: unknown;
  try { value = JSON.parse(text); } catch { return null; }
  if (!isRecord(value) || !hasKeys(value, ["version", "boardCode", "matched", "selection", "moves", "elapsedMs", "started"])) return null;
  if (value.version !== FORMAT_VERSION || typeof value.boardCode !== "string" || !Array.isArray(value.matched)) return null;
  if (!isCount(value.moves, MAX_MOVES) || !isCount(value.elapsedMs, MAX_ELAPSED_MS) || typeof value.started !== "boolean") return null;
  const board = parseBoardCode(value.boardCode);
  if (!board) return null;
  const positions = new Set<number>();
  for (const position of value.matched) {
    if (!isPosition(position, board.deck.length) || positions.has(position)) return null;
    positions.add(position);
  }
  for (const position of positions) {
    const face = board.deck[position];
    if (face === undefined) return null;
    const pair = board.deck.flatMap((candidate, index) => candidate === face ? [index] : []);
    if (pair.some((index) => !positions.has(index))) return null;
  }
  const selection = readSelection(value.selection, board.deck, positions);
  if (!selection || (positions.size === board.deck.length && selection.kind !== "closed")) return null;
  const pairs = positions.size / 2;
  if (value.moves < pairs + (selection.kind === "mismatch" ? 1 : 0)) return null;
  if (!value.started && (value.moves !== 0 || value.elapsedMs !== 0 || positions.size !== 0 || selection.kind !== "closed")) return null;
  if (value.started && value.moves === 0 && selection.kind !== "one") return null;
  return Object.freeze({ board, matched: Object.freeze([...positions]), selection, moves: value.moves, elapsedMs: value.elapsedMs, started: value.started });
}
import { FORMAT_VERSION, REPLAY_LIMIT_ACTIONS, REPLAY_LIMIT_BYTES } from "./constants.js";
import { createGame } from "./board.js";
import { activateCard, advanceGame } from "./transitions.js";
import type { GameState } from "./types.js";

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);
const hasKeys = (value: Record<string, unknown>, keys: readonly string[]): boolean =>
  Object.keys(value).length === keys.length && keys.every((key) => Object.hasOwn(value, key));
const isTime = (value: unknown): value is number =>
  typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
function isUnknownArray(value: unknown): value is unknown[] { return Array.isArray(value); }

export function replayGame(text: string): GameState | null {
  if (new TextEncoder().encode(text).byteLength > REPLAY_LIMIT_BYTES) return null;
  let value: unknown;
  try { value = JSON.parse(text); } catch { return null; }
  if (!isRecord(value) || !hasKeys(value, ["version", "boardCode", "actions", "endMs"])) return null;
  if (value.version !== FORMAT_VERSION || typeof value.boardCode !== "string" || !isTime(value.endMs) || !isUnknownArray(value.actions)) return null;
  if (value.actions.length > REPLAY_LIMIT_ACTIONS) return null;
  const initial = createGame(value.boardCode);
  if (!initial) return null;
  let state = initial;
  let previousTime = 0;
  for (const item of value.actions) {
    if (!isRecord(item) || !hasKeys(item, ["atMs", "index"]) || !isTime(item.atMs)) return null;
    const atMs = item.atMs;
    const index = item.index;
    if (!Number.isSafeInteger(index) || typeof index !== "number" || index < 0 || index >= state.board.deck.length) return null;
    if (atMs < previousTime || atMs > value.endMs) return null;
    state = advanceGame(state, atMs - previousTime);
    state = activateCard(state, index);
    previousTime = atMs;
  }
  return advanceGame(state, value.endMs - previousTime);
}

import { readFile } from "node:fs/promises";
import { encodeSnapshot } from "../src/game/snapshot.ts";
import { replayGame } from "../src/game/replay.ts";

const path = process.argv[2];
if (!path || process.argv.length !== 3) {
  process.stderr.write("Usage: npm run --silent replay -- PATH\n");
  process.exitCode = 1;
} else {
  try {
    const text = await readFile(path, "utf8");
    const state = replayGame(text);
    if (!state) {
      process.stderr.write("Invalid replay.\n");
      process.exitCode = 1;
    } else {
      process.stdout.write(`${encodeSnapshot(state)}\n`);
    }
  } catch {
    process.stderr.write("Unable to read replay file.\n");
    process.exitCode = 1;
  }
}
import { describe, expect, it } from "vitest";
import { createGame, parseBoardCode, SUPPORTED_SIZES } from "./board.ts";

describe("board codes and seeded deals", () => {
  it("matches the documented Park–Miller shuffle vector", () => {
    expect(createGame("np1-4-1")?.board.deck).toEqual([6, 7, 0, 5, 2, 2, 0, 5, 3, 7, 1, 6, 4, 4, 1, 3]);
  });

  it("builds complete pairs for every supported size", () => {
    for (const size of SUPPORTED_SIZES) {
      const game = createGame(`np1-${size}-2147483646`);
      expect(game?.board.deck).toHaveLength(size * size);
      const counts = new Map<number, number>();
      for (const face of game?.board.deck ?? []) counts.set(face, (counts.get(face) ?? 0) + 1);
      expect([...counts.values()].every((count) => count === 2)).toBe(true);
    }
  });

  it("accepts only canonical supported codes and safe seeds", () => {
    expect(parseBoardCode("np1-4-1")?.code).toBe("np1-4-1");
    for (const bad of [" np1-4-1", "np1-4-1\n", "np1-04-1", "np1-5-1", "np1-4-0", "np1-4-01", "np1-4-2147483647", "np2-4-1"]) {
      expect(parseBoardCode(bad)).toBeNull();
    }
  });
});
import { describe, expect, it } from "vitest";
import { createGame } from "./board.ts";
import { MAX_MOVES } from "./constants.ts";
import { decodeSnapshot } from "./snapshot.ts";
import { activateCard, advanceGame, isWon } from "./transitions.ts";

const startingGame = () => createGame("np1-4-1");

describe("card transitions and active time", () => {
  it("ignores repeated selection until a different card is revealed", () => {
    const game = startingGame();
    if (!game) throw new Error("fixture board is valid");
    const one = activateCard(game, 0);
    expect(activateCard(one, 0)).toBe(one);
    expect(one.moves).toBe(0);
    const two = activateCard(one, 11);
    expect(two.moves).toBe(1);
    expect(two.matched).toEqual([0, 11]);
    expect(two.selection.kind).toBe("closed");
  });

  it("keeps a miss for 800 active milliseconds and blocks actions", () => {
    const game = startingGame();
    if (!game) throw new Error("fixture board is valid");
    const mismatch = activateCard(activateCard(game, 0), 1);
    expect(mismatch.selection).toEqual({ kind: "mismatch", first: 0, second: 1, remainingMs: 800 });
    expect(activateCard(mismatch, 11)).toBe(mismatch);
    const beforeClose = advanceGame(mismatch, 799);
    expect(beforeClose.elapsedMs).toBe(799);
    expect(beforeClose.selection).toMatchObject({ kind: "mismatch", remainingMs: 1 });
    const closed = advanceGame(beforeClose, 1);
    expect(closed.selection).toEqual({ kind: "closed" });
    expect(closed.elapsedMs).toBe(800);
  });

  it("starts timing on first reveal, caps moves, and stops at victory", () => {
    const game = startingGame();
    if (!game) throw new Error("fixture board is valid");
    expect(advanceGame(game, 500)).toBe(game);
    const capInput = JSON.stringify({ version: 1, boardCode: game.board.code, matched: [], selection: { kind: "one", index: 0 }, moves: MAX_MOVES, elapsedMs: 0, started: true });
    const capped = decodeSnapshot(capInput);
    if (!capped) throw new Error("fixture snapshot is valid");
    const match = activateCard(capped, 11);
    expect(match.moves).toBe(MAX_MOVES);
    const winningBoard = createGame("np1-4-1");
    if (!winningBoard) throw new Error("fixture board is valid");
    let won = winningBoard;
    for (let index = 0; index < won.board.deck.length; index += 1) {
      const mate = won.board.deck.findIndex((face, other) => face === won.board.deck[index] && other !== index);
      won = activateCard(activateCard(won, index), mate);
    }
    expect(isWon(won)).toBe(true);
    expect(advanceGame(won, 100)).toBe(won);
  });
});
