import { BOARD_VERSION, PARK_MILLER_MODULUS, SUPPORTED_SIZES } from "./constants.ts";
import { SELECTION_KIND, type BoardDescription, type GridSize, type GameState } from "./types.ts";

export { SUPPORTED_SIZES } from "./constants.ts";

const isGridSize = (value: number): value is GridSize =>
  SUPPORTED_SIZES.some((size) => size === value);

export function parseBoardCode(text: string): BoardDescription | null {
  const match = /^(np1)-(4|6|8|10|12|14|16)-([1-9][0-9]*)$/.exec(text);
  if (!match || match[0] !== text) return null;
  const version = match[1];
  const sizeText = match[2];
  const seedText = match[3];
  if (!version || !sizeText || !seedText) return null;
  const size = Number(sizeText);
  const seed = Number(seedText);
  if (!isGridSize(size) || !Number.isSafeInteger(seed) || seed > PARK_MILLER_MODULUS - 1) return null;
  const code = `${version}-${size}-${seed}`;
  return Object.freeze({ code, size, seed, deck: Object.freeze(createDeck(size, seed)) });
}

function createDeck(size: GridSize, seed: number): number[] {
  const deck = Array.from({ length: size * size }, (_, index) => Math.floor(index / 2));
  let state = seed;
  const drawIndex = (bound: number): number => {
    const choices = PARK_MILLER_MODULUS - 1;
    const limit = Math.floor(choices / bound) * bound;
    let value = limit;
    while (value >= limit) {
      state = (state * 16_807) % PARK_MILLER_MODULUS;
      value = state - 1;
    }
    return value % bound;
  };
  for (let index = deck.length - 1; index > 0; index -= 1) {
    const other = drawIndex(index + 1);
    const currentFace = deck[index];
    const otherFace = deck[other];
    if (currentFace !== undefined && otherFace !== undefined) {
      deck[index] = otherFace;
      deck[other] = currentFace;
    }
  }
  return deck;
}

export function createGame(boardCode: string): GameState | null {
  const board = parseBoardCode(boardCode);
  if (!board) return null;
  return Object.freeze({
    board,
    matched: Object.freeze([]),
    selection: Object.freeze({ kind: SELECTION_KIND.CLOSED }),
    moves: 0,
    elapsedMs: 0,
    started: false,
  });
}

import { MAX_ELAPSED_MS } from "../constants.ts";

export function formatElapsedTime(milliseconds: number): string {
  const seconds = Math.floor(Math.min(milliseconds, MAX_ELAPSED_MS) / 1000);
  const minutes = Math.floor(seconds / 60);
  const remainder = String(seconds % 60).padStart(2, "0");
  return `${minutes}:${remainder}`;
}

export function makeFreshBoardCode(size: number, previousSeed?: number): string {
  const ceiling = 2_147_483_646;
  const bytes = new Uint32Array(1);
  let seed = 0;
  try {
    globalThis.crypto.getRandomValues(bytes);
    const value = bytes[0];
    seed = value === undefined ? 0 : (value % ceiling) + 1;
  } catch {
    seed = 0;
  }
  if (seed === 0) seed = Math.floor(Math.random() * ceiling) + 1;
  if (seed === previousSeed) seed = seed === ceiling ? 1 : seed + 1;
  return `np1-${size}-${seed}`;
}
import { MAX_MOVES } from "../constants.ts";
import { SUPPORTED_SIZES, type GridSize } from "../board.ts";

const GRID_KEY = "neon-pairs.grid-size.v1";
const BEST_KEY = "neon-pairs.best-moves.v1";

export type BestScores = Readonly<Partial<Record<GridSize, number>>>;
export type SavedPreferences = Readonly<{ gridSize: GridSize; bestScores: BestScores }>;

function isGridSize(value: unknown): value is GridSize {
  return typeof value === "number" && SUPPORTED_SIZES.some((size) => value === size);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseBestScores(value: unknown): BestScores {
  if (!isRecord(value)) return {};
  const scores: Partial<Record<GridSize, number>> = {};
  for (const size of SUPPORTED_SIZES) {
    const score = value[String(size)];
    if (typeof score === "number" && Number.isSafeInteger(score) && score >= 0 && score <= MAX_MOVES) {
      scores[size] = score;
    }
  }
  return scores;
}

export function readPreferences(): SavedPreferences {
  let gridSize: GridSize = 4;
  let bestScores: BestScores = {};
  try {
    const storedSize: unknown = JSON.parse(localStorage.getItem(GRID_KEY) ?? "null");
    if (isGridSize(storedSize)) gridSize = storedSize;
  } catch {
    // Storage and malformed JSON are optional; the fresh game still starts.
  }
  try {
    const storedScores: unknown = JSON.parse(localStorage.getItem(BEST_KEY) ?? "null");
    bestScores = parseBestScores(storedScores);
  } catch {
    // Keep whichever other preference was valid.
  }
  return { gridSize, bestScores };
}

export function saveGridSize(size: GridSize): void {
  try {
    localStorage.setItem(GRID_KEY, JSON.stringify(size));
  } catch {
    // A storage failure must not block a game action.
  }
}

export function saveBestScores(scores: BestScores): void {
  try {
    localStorage.setItem(BEST_KEY, JSON.stringify(scores));
  } catch {
    // In-memory scores stay available for this session.
  }
}
const COLORS = ["#63E7FF", "#FF71D6", "#8BEA7D", "#FFE082", "#FFB064", "#B49AFF", "#FF8296", "#D9F3FF"] as const;
const COLOR_NAMES = ["cyan", "magenta", "green", "yellow", "orange", "violet", "rose", "ice"] as const;
const SHAPES = ["circle", "square", "triangle", "diamond", "star", "hexagon", "plus", "chevron"] as const;
const MARKER_NAMES = ["top", "top-right", "right", "bottom-right", "bottom", "bottom-left", "left", "top-left"] as const;
const MARKERS = [
  { x: 50, y: 10 }, { x: 50 + 28.284, y: 50 - 28.284 }, { x: 90, y: 50 },
  { x: 50 + 28.284, y: 50 + 28.284 }, { x: 50, y: 90 },
  { x: 50 - 28.284, y: 50 + 28.284 }, { x: 10, y: 50 }, { x: 50 - 28.284, y: 50 - 28.284 },
] as const;

type FaceParts = Readonly<{ color: string; colorName: string; shape: string; marker: number; fill: "solid" | "outline" }>;

function partsFor(faceId: number): FaceParts {
  const shapeIndex = faceId % 8;
  const marker = Math.floor(faceId / 8) % 8;
  const fill = faceId >= 64 ? "outline" : "solid";
  return {
    color: COLORS[marker] ?? COLORS[0],
    colorName: COLOR_NAMES[marker] ?? COLOR_NAMES[0],
    shape: SHAPES[shapeIndex] ?? SHAPES[0],
    marker,
    fill,
  };
}

export function faceName(faceId: number): string {
  const face = partsFor(faceId);
  return `${face.colorName} ${face.fill} ${face.shape}, marker ${MARKER_NAMES[face.marker] ?? MARKER_NAMES[0]}`;
}

function starPoints(): string {
  return Array.from({ length: 10 }, (_, index) => {
    const angle = index * Math.PI / 5 - Math.PI / 2;
    const radius = index % 2 === 0 ? 25 : 11;
    return `${50 + Math.cos(angle) * radius},${50 + Math.sin(angle) * radius}`;
  }).join(" ");
}

function shapeNode(shape: string, fill: string, stroke: string, outline: boolean): ReactNode {
  const attributes = { fill: outline ? "none" : fill, stroke: outline ? stroke : "none", strokeWidth: outline ? 5 : undefined };
  switch (shape) {
    case "circle": return <circle cx="50" cy="50" r="25" {...attributes} />;
    case "square": return <rect x="25" y="25" width="50" height="50" {...attributes} />;
    case "triangle": return <polygon points="50,25 75,75 25,75" {...attributes} />;
    case "diamond": return <polygon points="50,25 75,50 50,75 25,50" {...attributes} />;
    case "star": return <polygon points={starPoints()} {...attributes} />;
    case "hexagon": return <polygon points="37.5,25 62.5,25 75,50 62.5,75 37.5,75 25,50" {...attributes} />;
    case "plus": return <polygon points="38,25 62,25 62,38 75,38 75,62 62,62 62,75 38,75 38,62 25,62 25,38 38,38" {...attributes} />;
    case "chevron": return <polygon points="32,25 75,50 32,75 25,66 53,50 25,34" {...attributes} />;
  }
}

export function FaceArtwork({ faceId }: Readonly<{ faceId: number }>) {
  const face = partsFor(faceId);
  const marker = MARKERS[face.marker] ?? MARKERS[0];
  return (
    <svg className="face-art" viewBox="0 0 100 100" aria-hidden="true" focusable="false">
      {shapeNode(face.shape, face.color, face.color, face.fill === "outline")}
      <circle cx={marker.x} cy={marker.y} r="5" fill={face.color} stroke="#111625" strokeWidth="3" />
